from __future__ import annotations

from collections import Counter


class Inventory:
    def __init__(self) -> None:
        self._stock: Counter[str] = Counter()

    def receive(self, sku: str, quantity: int) -> None:
        if quantity <= 0:
            raise ValueError("received quantity must be positive")
        self._stock[sku] += quantity

    def reserve(self, sku: str, quantity: int) -> bool:
        if self._stock[sku] < quantity:
            return False
        self._stock[sku] -= quantity
        return True

    def low_stock_skus(self, threshold: int = 3) -> list[str]:
        return sorted(sku for sku, count in self._stock.items() if count <= threshold)
